INSERT INTO `products` VALUES (1,'Avon Titan Wireless Rotary Pen Machine','avon-titan-wireless-rotary-pen',NULL,'Engineered for precision lining and smooth shading. Includes a custom brushless motor, ultra-durable aircraft aluminium casing, and 2,000mAh dual wireless battery packs offering up to 10 hours of continuous tattooing.','[{\"question\":\"What stroke length option is best for lining?\",\"answer\":\"The 4.0mm stroke option provides the highest punch for crisp 09RL to 18RL line work, while 3.5mm is ideal for all-round shading and color packing.\"},{\"question\":\"Is it compatible with Cheyenne needle cartridges?\",\"answer\":\"Yes, it features a universal locking mechanism compatible with all standard membrane cartridge needles.\"}]',18999.00,NULL,45,'Machines','',NULL,1,'2026-09-17 15:49:43','2026-10-21 16:42:23'),(2,'Avon Precision Pro Sterilized Needle Cartridges (Box of 20)','avon-precision-pro-cartridges',NULL,'Medical-grade 316L stainless steel needles with safety membrane technology to prevent backflow into your machine grip. EO gas sterilized and individually packaged.','[{\"question\":\"What gauge corresponds to #10 vs #12?\",\"answer\":\"#10 gauge is 0.30mm (bugpin for fine detail), while #12 gauge is 0.35mm (standard size for solid saturation).\"},{\"question\":\"Does it contain a backflow safety membrane?\",\"answer\":\"Yes, 100% backflow sealed high-flexibility silicon membrane.\"}]',1499.00,NULL,200,'Needles','',NULL,1,'2026-09-17 15:49:43','2026-10-21 16:42:23'),(3,'Obsidian Black Triple Concentrated Lining Ink 240ml','obsidian-black-lining-ink-240ml',NULL,'Deepest black ink formulated specifically for bold outlines and solid tribal blackwork. High pigment load ensures quick skin absorption and healed vibrancy without blue shifting.','[{\"question\":\"Is this ink vegan and cruelty-free?\",\"answer\":\"Yes, 100% vegan pigment formulation free of animal by-products and gamma-ray sterilized.\"}]',2499.00,NULL,78,'Inks','',NULL,1,'2026-09-17 15:49:43','2026-10-21 16:42:23'),(4,'Avon Force Dual Output Digital Power Supply','avon-force-dual-output-power-supply',NULL,'Microprocessor-controlled digital power supply with LED voltage readout, jump-start mode for heavy rotary machines, and smart dual machine connection toggle.','[{\"question\":\"Does it support foot pedal-free continuous mode?\",\"answer\":\"Yes, built-in momentary and continuous pedal override mode allows running without a foot switch.\"}]',6999.00,NULL,29,'Power Supplies','',NULL,1,'2026-09-17 15:49:43','2026-10-21 16:42:23'),(5,'The Machine of the Tattoo New','the-machine-of-the-tattoo-new','Type','Surgical grade professional tattoo equipment engineered for lining and shading.','[{\"question\":\"Is this compatible with standard cartridge grips?\",\"answer\":\"Yes, 100% universal Cheyenne membrane standard.\"}]',6676.00,4999.00,10,'Machines','http://localhost/tatrabbit/avon-tattoo-store/backend/uploads/products/prod_1790964690_187be90e.png','[\"http:\\/\\/localhost\\/tatrabbit\\/avon-tattoo-store\\/backend\\/uploads\\/products\\/prod_1790964690_187be90e.png\",\"http:\\/\\/localhost\\/tatrabbit\\/avon-tattoo-store\\/backend\\/uploads\\/products\\/prod_1790964935_2b0e50f2.png\",\"http:\\/\\/localhost\\/tatrabbit\\/avon-tattoo-store\\/backend\\/uploads\\/products\\/prod_1790964941_76927f41.png\",\"http:\\/\\/localhost\\/tatrabbit\\/avon-tattoo-store\\/backend\\/uploads\\/products\\/prod_1790964946_83d5fc22.png\"]',1,'2026-10-02 18:16:23','2026-10-16 17:10:12'),(6,'Best New product 2026','best-new-product-2026','','','[{\"question\":\"Is this compatible with standard cartridge grips?\",\"answer\":\"Yes, 100% universal Cheyenne membrane standard.\"}]',5999.00,NULL,7,'New 2026','','[]',1,'2026-10-06 16:11:47','2026-10-08 17:10:48');
