INSERT INTO `reviews` VALUES (1,NULL,'Avon Titan Wireless Rotary Pen Machine','Jack S.','Ink Therapy Studio, Mumbai',5,'The 4.0mm stroke on the Titan Rotary is phenomenal for 14RL lining. Zero battery lag after 6 hours of shading!',NULL,NULL,0,'2026-09-17 17:09:48'),(2,NULL,'Avon Precision Pro Cartridges','Priya M.','Dark Canvas Tattoo, Delhi',5,'Best membrane tension I have tested in 8 years. Zero backflow into my machine grips and razor-sharp needles.',NULL,NULL,1,'2026-09-17 17:09:48'),(3,NULL,'Obsidian Black Lining Ink','Rohan V.','Blackout Studio, Goa',5,'Extremely dark lining ink! Heals jet black without blue shifting. Ordered 5 bottles for our studio.',NULL,NULL,1,'2026-09-17 17:09:48'),(4,NULL,'Avon Force Digital Power Supply','Aman K.','Tattoo Temple, Bengaluru',4,'Solid digital output, heavy-duty jumpstart mode works great with stiff rotary coils.',NULL,NULL,0,'2026-09-17 17:09:48'),(5,NULL,'Avon Equipment','hhhh','hhhhh',5,'hhhhhh',NULL,NULL,0,'2026-09-17 17:19:07');
